//! Google Docs, Sheets, Slides and Drawings in a mirrored folder. They have no file to download,
//! so like the original they appear as small link files (`.gdoc`, `.gsheet`, `.gslides`) that
//! open the document in the browser. The original's flag `allowed_new_gdoc_file_name_pattern`
//! (0x103f4c2e6) = `.*Google Docs.*\.gdoc|.*Google Sheets.*\.gsheet|.*Google Slides.*\.gslides`
//! names these types, and the files hold its warning text "WARNING! DO NOT EDIT THIS FILE! ANY
//! CHANGES MADE WILL BE LOST!" (0x102bf5895) with the document's `doc_id`.
//!
//! The link files stay on this computer: they are never uploaded, and they are rewritten when the
//! document is renamed or moved on Drive and removed when it is deleted there.
use std::collections::BTreeSet;
use std::path::Path;

pub const WARNING: &str = "WARNING! DO NOT EDIT THIS FILE! ANY CHANGES MADE WILL BE LOST!";

/// Google type (application/vnd.google-apps.<type>) → link file extension → where it opens
/// ("" = Drive's own opener). The extensions and their order follow the original's table at
/// 0x1042a7740 (type number, extension): gdoc 2, gslides 3, gform 4, gsheet 5, gdraw 6, gtable 7,
/// gmap 8, gscript 9, gsite 10, gmaillayout 11, gnote 12, glink 13, gjam 14, gvid 15, gprj 16,
/// gpic 17, read by function 0x100d541bd. Extensions with no Drive type name are kept so their
/// files are still recognised and never uploaded.
const KINDS: &[(&str, &str, &str)] = &[
    ("document", "gdoc", "https://docs.google.com/document/d/{id}/edit"),
    ("presentation", "gslides", "https://docs.google.com/presentation/d/{id}/edit"),
    ("form", "gform", "https://docs.google.com/forms/d/{id}/edit"),
    ("spreadsheet", "gsheet", "https://docs.google.com/spreadsheets/d/{id}/edit"),
    ("drawing", "gdraw", "https://docs.google.com/drawings/d/{id}/edit"),
    ("fusiontable", "gtable", ""),
    ("map", "gmap", ""),
    ("script", "gscript", "https://script.google.com/d/{id}/edit"),
    ("site", "gsite", ""),
    ("mail-layout", "gmaillayout", ""),
    ("", "gnote", ""),
    ("", "glink", ""),
    ("jam", "gjam", ""),
    ("vid", "gvid", ""),
    ("", "gprj", ""),
    ("", "gpic", ""),
];

#[derive(Clone, Debug, PartialEq)]
pub struct Doc {
    /// Link file path relative to the mirrored folder, e.g. "Work/Budget.gsheet".
    pub path: String,
    pub id: String,
}

/// Whether a name is one of the link files (never uploaded or mirrored as a file).
pub fn is_link(name: &str) -> bool {
    let lower = name.to_lowercase();
    KINDS.iter().any(|(_, ext, _)| lower.ends_with(&format!(".{ext}")))
}

/// rclone --exclude arguments that keep link files out of the computer's file list.
pub fn exclude_args() -> Vec<String> {
    KINDS.iter().flat_map(|(_, ext, _)| ["--exclude".to_string(), format!("*.{ext}")]).collect()
}

/// Google documents in `rclone lsjson -R --files-only --drive-show-all-gdocs` output: the entries
/// with no size and a Google type, listed under their own name (shortcuts and types the original
/// has no extension for are left out).
pub fn parse_docs(json: &[u8]) -> Vec<Doc> {
    let Ok(serde_json::Value::Array(items)) = serde_json::from_slice::<serde_json::Value>(json) else { return Vec::new() };
    let mut out = Vec::new();
    for item in items {
        if item["IsDir"].as_bool().unwrap_or(false) || item["Size"].as_i64().unwrap_or(0) >= 0 {
            continue;
        }
        let (Some(path), Some(id)) = (item["Path"].as_str(), item["ID"].as_str()) else { continue };
        let Some(kind) = item["MimeType"].as_str().and_then(|m| m.strip_prefix("application/vnd.google-apps.")) else { continue };
        let Some((_, link, _)) = KINDS.iter().find(|(k, _, _)| !k.is_empty() && *k == kind) else { continue };
        if !path.is_empty() && !id.is_empty() {
            out.push(Doc { path: format!("{path}.{link}"), id: id.to_string() });
        }
    }
    out
}

/// The web address of a document from its link file's name and id.
pub fn url(link_name: &str, id: &str) -> String {
    let lower = link_name.to_lowercase();
    match KINDS.iter().find(|(_, ext, _)| lower.ends_with(&format!(".{ext}"))).map(|k| k.2) {
        Some(u) if !u.is_empty() => u.replace("{id}", id),
        _ => format!("https://drive.google.com/open?id={id}"),
    }
}

/// The link file's contents (the original's fields, plus the address so any program can open it).
pub fn body(doc: &Doc, email: &str) -> String {
    serde_json::json!({
        "": WARNING,
        "doc_id": doc.id,
        "resource_key": "",
        "email": email,
        "url": url(&doc.path, &doc.id),
    })
    .to_string()
}

/// Writes a link file for every document and removes the ones whose document is gone (only files
/// that still carry the warning text, so nothing the person made is touched). Returns how many
/// link files were added.
pub fn write_links(folder: &str, docs: &[Doc], email: &str, previous: &BTreeSet<String>) -> usize {
    let mut added = 0;
    let current: BTreeSet<&str> = docs.iter().map(|d| d.path.as_str()).collect();
    for d in docs {
        let path = Path::new(folder).join(&d.path);
        let text = body(d, email);
        if std::fs::read_to_string(&path).map(|t| t == text).unwrap_or(false) {
            continue;
        }
        if let Some(dir) = path.parent() {
            let _ = std::fs::create_dir_all(dir);
        }
        let existed = path.exists();
        if std::fs::write(&path, text).is_ok() && !existed {
            added += 1;
        }
    }
    for old in previous.iter().filter(|p| !current.contains(p.as_str())) {
        let path = Path::new(folder).join(old);
        if std::fs::read_to_string(&path).map(|t| t.contains(WARNING)).unwrap_or(false) {
            let _ = std::fs::remove_file(path);
        }
    }
    added
}

/// Opens a link file's document in the browser (`drive-linux --open-doc <file>`).
pub fn open(file: &Path) -> bool {
    let Ok(text) = std::fs::read_to_string(file) else { return false };
    let Ok(v) = serde_json::from_str::<serde_json::Value>(&text) else { return false };
    let name = file.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
    let target = match (v["url"].as_str(), v["doc_id"].as_str()) {
        (Some(u), _) if u.starts_with("https://") => u.to_string(),
        (_, Some(id)) if !id.is_empty() => url(&name, id),
        _ => return false,
    };
    std::process::Command::new("xdg-open").arg(target).stdout(std::process::Stdio::null()).stderr(std::process::Stdio::null()).spawn().is_ok()
}

/// Shared MIME type file so file managers open the link files with this app.
pub const MIME_XML: &str = include_str!("../packaging/drive-linux-mime.xml");

/// The file types the opener handles, one per link extension ("application/x-drive-linux-gsheet;…").
pub fn mime_types() -> String {
    KINDS.iter().map(|(_, ext, _)| format!("application/x-drive-linux-{ext};")).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn google_documents_become_link_files() {
        // As rclone 1.76 lists them with --drive-show-all-gdocs (seen on the person's account).
        let json = br#"[
            {"Path":"test","Name":"test","Size":-1,"MimeType":"application/vnd.google-apps.spreadsheet","IsDir":false,"ID":"1iHi"},
            {"Path":"Work/Plan","Name":"Plan","Size":-1,"MimeType":"application/vnd.google-apps.document","IsDir":false,"ID":"2ab"},
            {"Path":"real.xlsx","Name":"real.xlsx","Size":4096,"MimeType":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","IsDir":false,"ID":"3cd"},
            {"Path":"Deck","Name":"Deck","Size":-1,"MimeType":"application/vnd.google-apps.presentation","IsDir":false,"ID":"4ef"},
            {"Path":"Survey","Name":"Survey","Size":-1,"MimeType":"application/vnd.google-apps.form","IsDir":false,"ID":"5gh"},
            {"Path":"Trip","Name":"Trip","Size":-1,"MimeType":"application/vnd.google-apps.map","IsDir":false,"ID":"6ij"},
            {"Path":"Link","Name":"Link","Size":-1,"MimeType":"application/vnd.google-apps.shortcut","IsDir":false,"ID":"7kl"}
        ]"#;
        let docs = parse_docs(json);
        let d = |p: &str, id: &str| Doc { path: p.into(), id: id.into() };
        assert_eq!(docs, vec![d("test.gsheet", "1iHi"), d("Work/Plan.gdoc", "2ab"), d("Deck.gslides", "4ef"), d("Survey.gform", "5gh"), d("Trip.gmap", "6ij")]);
        assert_eq!(url("test.gsheet", "1iHi"), "https://docs.google.com/spreadsheets/d/1iHi/edit");
        assert_eq!(url("Trip.gmap", "6ij"), "https://drive.google.com/open?id=6ij");
        assert!(is_link("Work/Plan.GDOC") && is_link("Board.gjam") && !is_link("real.xlsx"));
        assert_eq!(KINDS.len(), 16, "the original's table has 16 link extensions");
    }

    #[test]
    fn packaged_file_types_cover_every_link_extension() {
        let desktop = include_str!("../packaging/drive-linux-open-doc.desktop");
        assert!(desktop.contains(&format!("MimeType={}\n", mime_types())));
        for (_, ext, _) in KINDS {
            assert!(MIME_XML.contains(&format!("<glob pattern=\"*.{ext}\"/>")), "{ext}");
        }
    }

    #[test]
    fn link_files_are_written_and_removed() {
        let dir = std::env::temp_dir().join(format!("drive-linux-gdocs-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let folder = dir.to_string_lossy().to_string();
        let a = Doc { path: "Sub/A.gsheet".into(), id: "x1".into() };
        assert_eq!(write_links(&folder, std::slice::from_ref(&a), "me@example.com", &BTreeSet::new()), 1);
        let text = std::fs::read_to_string(dir.join("Sub/A.gsheet")).unwrap();
        assert!(text.contains(WARNING) && text.contains("\"doc_id\":\"x1\"") && text.contains("spreadsheets/d/x1/edit"));
        // The person's own file with the same kind of name is never removed.
        std::fs::write(dir.join("Mine.gsheet"), "my notes").unwrap();
        let prev: BTreeSet<String> = ["Sub/A.gsheet".to_string(), "Mine.gsheet".to_string()].into();
        write_links(&folder, &[], "me@example.com", &prev);
        assert!(!dir.join("Sub/A.gsheet").exists());
        assert!(dir.join("Mine.gsheet").exists());
        let _ = std::fs::remove_dir_all(&dir);
    }
}
